export function applyCoupon(cart: Cart, coupon: Coupon) {
  if (cart.couponCode === coupon.code) return cart;
  cart.couponCode = coupon.code;
  cart.total = cart.subtotal * (1 - coupon.percent / 100);
  return cart;
}

